/// The double-width sum `a + b` of 12 limbs, for a sum that fits.
#[inline(always)]
pub(super) fn wide_add6(a: &[u64; 12], b: &[u64; 12]) -> [u64; 12] {
    let mut o = [0u64; 12];
    // SAFETY: the block reads the operands' limbs through the pointers given, which point
    // to arrays of the lengths read, writes only the registers declared, and leaves the
    // stack alone.
    unsafe {
        asm!(
            "ldp {o0}, {o1}, [{ap}]",
            "ldp {o2}, {o3}, [{ap}, #16]",
            "ldp {o4}, {o5}, [{ap}, #32]",
            "ldp {o6}, {o7}, [{ap}, #48]",
            "ldp {o8}, {o9}, [{ap}, #64]",
            "ldp {o10}, {o11}, [{ap}, #80]",
            "ldp {q0}, {q1}, [{bp}]",
            "adds {o0}, {o0}, {q0}",
            "adcs {o1}, {o1}, {q1}",
            "ldp {q0}, {q1}, [{bp}, #16]",
            "adcs {o2}, {o2}, {q0}",
            "adcs {o3}, {o3}, {q1}",
            "ldp {q0}, {q1}, [{bp}, #32]",
            "adcs {o4}, {o4}, {q0}",
            "adcs {o5}, {o5}, {q1}",
            "ldp {q0}, {q1}, [{bp}, #48]",
            "adcs {o6}, {o6}, {q0}",
            "adcs {o7}, {o7}, {q1}",
            "ldp {q0}, {q1}, [{bp}, #64]",
            "adcs {o8}, {o8}, {q0}",
            "adcs {o9}, {o9}, {q1}",
            "ldp {q0}, {q1}, [{bp}, #80]",
            "adcs {o10}, {o10}, {q0}",
            "adcs {o11}, {o11}, {q1}",
            o0 = out(reg) o[0],
            o1 = out(reg) o[1],
            o2 = out(reg) o[2],
            o3 = out(reg) o[3],
            o4 = out(reg) o[4],
            o5 = out(reg) o[5],
            o6 = out(reg) o[6],
            o7 = out(reg) o[7],
            o8 = out(reg) o[8],
            o9 = out(reg) o[9],
            o10 = out(reg) o[10],
            o11 = out(reg) o[11],
            q0 = out(reg) _,
            q1 = out(reg) _,
            ap = in(reg) a.as_ptr(),
            bp = in(reg) b.as_ptr(),
            options(pure, readonly, nostack),
        );
    }
    o
}

